        // addAtIndex(0, val);
    &#125;


    public void addAtTail(int val) &#123;
        ListNode newNode = new ListNode(val);
        ListNode cur = head;
        while (cur.next != null) &#123;
            cur = cur.next;
        &#125;

        cur.next = newNode;
        size++;

        // 在链表的最后插入一个节点，等价于在(末尾+1)个元素前添加
        // addAtIndex(size, val);
