        size--;
        //因为有虚拟头节点，所以不用对Index=0的情况进行特殊处理
        ListNode pred = head;
        for (int i = 0; i &lt; index ; i++) &#123;
            pred = pred.next;
        &#125;
        pred.next = pred.next.next;
    &#125;
