class MyLinkedList &#123;  

    //记录链表中元素的数量
    int size;
    //记录链表的虚拟头结点和尾结点
    ListNode head,tail;

    public MyLinkedList() &#123;
        //初始化操作
        this.size = 0;
        this.head = new ListNode(0);
        this.tail = new ListNode(0);
        //这一步非常关键，否则在加入头结点的操作中会出现null.next的错误！！！
        head.next=tail;
        tail.prev=head;
    &#125;

    public int get(int index) &#123;
        //判断index是否有效
        if(index&gt;=size)&#123;
            return -1;
        &#125;
        ListNode cur = this.head;
        //判断是哪一边遍历时间更短
        if(index &gt;= size / 2)&#123;
            //tail开始
            cur = tail;
            for(int i=0; i&lt; size-index; i++)&#123;
                cur = cur.prev;
            &#125;
