    public void addAtIndex(int index, int val) &#123;
        //index大于链表长度
        if(index&gt;size)&#123;
            return;
        &#125;

        size++;
        //找到前驱
        ListNode pre = this.head;
        for(int i=0; i&lt;index; i++)&#123;
            pre = pre.next;
        &#125;
        //新建结点
        ListNode newNode = new ListNode(val);
        newNode.next = pre.next;
        pre.next.prev = newNode;
        newNode.prev = pre;
        pre.next = newNode;

