    public void deleteAtIndex(int index) &#123;
        //判断索引是否有效
        if(index&gt;=size)&#123;
            return;
        &#125;
        //删除操作
        size--;
        ListNode pre = this.head;
        for(int i=0; i&lt;index; i++)&#123;
            pre = pre.next;
        &#125;
        pre.next.next.prev = pre;
        pre.next = pre.next.next;
    &#125;
