cpp#include &lt;iostream&gt;
#include &lt;math.h&gt;

using namespace std;

int main() &#123;
    int n, ans, sum;
    int w[101], dp[101][10001];
    cin &gt;&gt; n;
    for (int i = 1; i &lt;= n; i++) &#123;
        cin &gt;&gt; w[i];
        sum += w[i];
    &#125;
    for (int i = 1; i &lt;= n; i++) &#123;
        for (int j = sum; j; j--) &#123;
            if (j == w[i])dp[i][j] = 1;
            else if (dp[i - 1][j])dp[i][j] = 1;
            else if (dp[i - 1][j + w[i]])dp[i][j] = 1;
            else if (dp[i - 1][abs(j - w[i])])dp[i][j] = 1;
        &#125;
    &#125;
    for (int i = 1; i &lt;= sum; i++) &#123;
        if (dp[n][i])ans++;
    &#125;
    cout &lt;&lt; ans;
    return 0;
