public:
    vector&lt;int&gt; maxSlidingWindow(vector&lt;int&gt;&amp; nums, int k) &#123;
        MyQueue que;
        vector&lt;int&gt; result;
        for (int i = 0; i &lt; k; i++) &#123; // 先将前k的元素放进队列
            que.push(nums[i]);
        &#125;
        result.push_back(que.front()); // result 记录前k的元素的最大值
        for (int i = k; i &lt; nums.size(); i++) &#123;
            que.pop(nums[i - k]); // 滑动窗口移除最前面元素
            que.push(nums[i]); // 滑动窗口前加入最后面的元素
            result.push_back(que.front()); // 记录对应的最大值
        &#125;
        return result;
    &#125;
&#125;;
时间复杂度: O(n)
空间复杂度: O(k)

再来看一下时间复杂度，使用单调队列的时间复杂度是 O(n)。
有的同学可能想了，在队列中 push元素的过程中，还有pop操作呢，感觉不是纯粹的O(n)。
其实，大家可以自己观察一下单调队列的实现，nums 中的每个元素最多也就被 push_back 和 pop_back 各一次，没有任何多余操作，所以整体的复杂度还是 O(n)。
空间复杂度因为我们定义一个辅助队列，所以是O(k)。
扩展：
大家貌似对单调队列 都有一些疑惑，首先要明确的是，题解中单调队列里的pop和push接口，仅适用于本题哈。单调队列不是一成不变的，而是不同场景不同写法，总之要保证队列里单调递减或递增的原则，所以叫做单调队列。 不要以为本题中的单调队列实现就是固定的写法哈。
大家貌似对deque也有一些疑惑，C++中deque是stack和queue默认的底层实现容器（这个我们之前已经讲过啦），deque是可以两边扩展的，而且deque里元素并不是严格的连续分布的。
Java：
java//解法一
//自定义数组
class MyQueue &#123;
    Deque&lt;Integer&gt; deque = new LinkedList&lt;&gt;();
    //弹出元素时，比较当前要弹出的数值是否等于队列出口的数值，如果相等则弹出
    //同时判断队列当前是否为空
    void poll(int val) &#123;
        if (!deque.isEmpty() &amp;&amp; val == deque.peek()) &#123;
            deque.poll();
        &#125;
    &#125;
    //添加元素时，如果要添加的元素大于入口处的元素，就将入口元素弹出
    //保证队列元素单调递减
    //比如此时队列元素3,1，2将要入队，比1大，所以1弹出，此时队列：3,2
    void add(int val) &#123;
        while (!deque.isEmpty() &amp;&amp; val &gt; deque.getLast()) &#123;
            deque.removeLast();
        &#125;
        deque.add(val);
    &#125;
    //队列队顶元素始终为最大值
    int peek() &#123;
        return deque.peek();
    &#125;
&#125;

class Solution &#123;
    public int[] maxSlidingWindow(int[] nums, int k) &#123;
        if (nums.length == 1) &#123;
            return nums;
        &#125;
        int len = nums.length - k + 1;
        //存放结果元素的数组
        int[] res = new int[len];
        int num = 0;
        //自定义队列
        MyQueue myQueue = new MyQueue();
        //先将前k的元素放入队列
        for (int i = 0; i &lt; k; i++) &#123;
            myQueue.add(nums[i]);
        &#125;
        res[num++] = myQueue.peek();
        for (int i = k; i &lt; nums.length; i++) &#123;
            //滑动窗口移除最前面的元素，移除是判断该元素是否放入队列
            myQueue.poll(nums[i - k]);
            //滑动窗口加入最后面的元素
            myQueue.add(nums[i]);
            //记录对应的最大值
            res[num++] = myQueue.peek();
        &#125;
        return res;
    &#125;
&#125;

//解法二
//利用双端队列手动实现单调队列
/**
 * 用一个单调队列来存储对应的下标，每当窗口滑动的时候，直接取队列的头部指针对应的值放入结果集即可
 * 单调队列类似 （tail --&gt;） 3 --&gt; 2 --&gt; 1 --&gt; 0 (--&gt; head) (右边为头结点，元素存的是下标)
 */
class Solution &#123;
    public int[] maxSlidingWindow(int[] nums, int k) &#123;
        ArrayDeque&lt;Integer&gt; deque = new ArrayDeque&lt;&gt;();
        int n = nums.length;
        int[] res = new int[n - k + 1];
        int idx = 0;
        for(int i = 0; i &lt; n; i++) &#123;
            // 根据题意，i为nums下标，是要在[i - k + 1, i] 中选到最大值，只需要保证两点
            // 1.队列头结点需要在[i - k + 1, i]范围内，不符合则要弹出
            while(!deque.isEmpty() &amp;&amp; deque.peek() &lt; i - k + 1)&#123;
                deque.poll();
            &#125;
            // 2.既然是单调，就要保证每次放进去的数字要比末尾的都大，否则也弹出
            while(!deque.isEmpty() &amp;&amp; nums[deque.peekLast()] &lt; nums[i]) &#123;
                deque.pollLast();
            &#125;

            deque.offer(i);

            // 因为单调，当i增长到符合第一个k范围的时候，每滑动一步都将队列头节点放入结果就行了
            if(i &gt;= k - 1)&#123;
                res[idx++] = nums[deque.peek()];
            &#125;
        &#125;
        return res;
    &#125;
&#125;8.前 K 个高频元素给定一个非空的整数数组，返回其中出现频率前 k 高的元素。
示例 1:

输入: nums &#x3D; [1,1,1,2,2,3], k &#x3D; 2
输出: [1,2]

示例 2:

输入: nums &#x3D; [1], k &#x3D; 1
输出: [1]

提示：

你可以假设给定的 k 总是合理的，且 1 ≤ k ≤ 数组中不相同的元素的个数。
你的算法的时间复杂度必须优于 $O(n \log n)$ , n 是数组的大小。
题目数据保证答案唯一，换句话说，数组中前 k 个高频元素的集合是唯一的。
你可以按任意顺序返回答案。

思路：
这道题目主要涉及到如下三块内容：

要统计元素出现频率
对频率排序
找出前K个高频元素

首先统计元素出现的频率，这一类的问题可以使用map来进行统计。
然后是对频率进行排序，这里我们可以使用一种 容器适配器就是优先级队列。
什么是优先级队列呢？
其实就是一个披着队列外衣的堆，因为优先级队列对外接口只是从队头取元素，从队尾添加元素，再无其他取元素的方式，看起来就是一个队列。
而且优先级队列内部元素是自动依照元素的权值排列。那么它是如何有序排列的呢？
缺省情况下priority_queue利用max-heap（大顶堆）完成对元素的排序，这个大顶堆是以vector为表现形式的complete binary tree（完全二叉树）。
什么是堆呢？
堆是一棵完全二叉树，树中每个结点的值都不小于（或不大于）其左右孩子的值。 如果父亲结点是大于等于左右孩子就是大顶堆，小于等于左右孩子就是小顶堆。
所以大家经常说的大顶堆（堆头是最大元素），小顶堆（堆头是最小元素），如果懒得自己实现的话，就直接用priority_queue（优先级队列）就可以了，底层实现都是一样的，从小到大排就是小顶堆，从大到小排就是大顶堆。
本题我们就要使用优先级队列来对部分频率进行排序。
为什么不用快排呢， 使用快排要将map转换为vector的结构，然后对整个数组进行排序， 而这种场景下，我们其实只需要维护k个有序的序列就可以了，所以使用优先级队列是最优的。
此时要思考一下，是使用小顶堆呢，还是大顶堆？
有的同学一想，题目要求前 K 个高频元素，那么果断用大顶堆啊。
那么问题来了，定义一个大小为k的大顶堆，在每次移动更新大顶堆的时候，每次弹出都把最大的元素弹出去了，那么怎么保留下来前K个高频元素呢。
而且使用大顶堆就要把所有元素都进行排序，那能不能只排序k个元素呢？
所以我们要用小顶堆，因为要统计最大前k个元素，只有小顶堆每次将最小的元素弹出，最后小顶堆里积累的才是前k个最大元素。
寻找前k个最大元素流程如图所示：（图中的频率只有三个，所以正好构成一个大小为3的小顶堆，如果频率更多一些，则用这个小顶堆进行扫描）

java/*Comparator接口说明:
 * 返回负数，形参中第一个参数排在前面；返回正数，形参中第二个参数排在前面
 * 对于队列：排在前面意味着往队头靠
 * 对于堆（使用PriorityQueue实现）：从队头到队尾按从小到大排就是最小堆（小顶堆），
 *                                从队头到队尾按从大到小排就是最大堆（大顶堆）---&gt;队头元素相当于堆的根节点
 * */
class Solution &#123;
    //解法1：基于大顶堆实现
    public int[] topKFrequent1(int[] nums, int k) &#123;
        Map&lt;Integer,Integer&gt; map = new HashMap&lt;&gt;(); //key为数组元素值,val为对应出现次数
        for (int num : nums) &#123;
            map.put(num, map.getOrDefault(num,0) + 1);
        &#125;
        //在优先队列中存储二元组(num, cnt),cnt表示元素值num在数组中的出现次数
        //出现次数按从队头到队尾的顺序是从大到小排,出现次数最多的在队头(相当于大顶堆)
        PriorityQueue&lt;int[]&gt; pq = new PriorityQueue&lt;&gt;((pair1, pair2) -&gt; pair2[1] - pair1[1]);
        for (Map.Entry&lt;Integer, Integer&gt; entry : map.entrySet()) &#123;//大顶堆需要对所有元素进行排序
            pq.add(new int[]&#123;entry.getKey(), entry.getValue()&#125;);
        &#125;
        int[] ans = new int[k];
        for (int i = 0; i &lt; k; i++) &#123; //依次从队头弹出k个,就是出现频率前k高的元素
            ans[i] = pq.poll()[0];
        &#125;
        return ans;
    &#125;
    //解法2：基于小顶堆实现
    public int[] topKFrequent2(int[] nums, int k) &#123;
        Map&lt;Integer,Integer&gt; map = new HashMap&lt;&gt;(); //key为数组元素值,val为对应出现次数
        for (int num : nums) &#123;
            map.put(num, map.getOrDefault(num, 0) + 1);
        &#125;
        //在优先队列中存储二元组(num, cnt),cnt表示元素值num在数组中的出现次数
        //出现次数按从队头到队尾的顺序是从小到大排,出现次数最低的在队头(相当于小顶堆)
        PriorityQueue&lt;int[]&gt; pq = new PriorityQueue&lt;&gt;((pair1, pair2) -&gt; pair1[1] - pair2[1]);
        for (Map.Entry&lt;Integer, Integer&gt; entry : map.entrySet()) &#123; //小顶堆只需要维持k个元素有序
            if (pq.size() &lt; k) &#123; //小顶堆元素个数小于k个时直接加
                pq.add(new int[]&#123;entry.getKey(), entry.getValue()&#125;);
            &#125; else &#123;
                if (entry.getValue() &gt; pq.peek()[1]) &#123; //当前元素出现次数大于小顶堆的根结点(这k个元素中出现次数最少的那个)
                    pq.poll(); //弹出队头(小顶堆的根结点),即把堆里出现次数最少的那个删除,留下的就是出现次数多的了
                    pq.add(new int[]&#123;entry.getKey(), entry.getValue()&#125;);
                &#125;
            &#125;
        &#125;
        int[] ans = new int[k];
        for (int i = k - 1; i &gt;= 0; i--) &#123; //依次弹出小顶堆,先弹出的是堆的根,出现次数少,后面弹出的出现次数多
            ans[i] = pq.poll()[0];
        &#125;
        return ans;
    &#125;
&#125;简化版代码：
