    @ConditionalOnClass(name=&quot;io.jsonwebtoken.Jwts&quot;)//环境中存在指定的这个类，才会将该bean加入IOC容器
    public HeaderParser headerParser()&#123;
        return new HeaderParser();
    &#125;

    //省略其他代码...
