&lt;/select&gt;
动态SQL语句

xml&lt;select id=&quot;list&quot; resultType=&quot;com.itheima.pojo.Emp&quot;&gt;
        select * from emp
        where

             &lt;if test=&quot;name != null&quot;&gt;
                 name like concat(&#39;%&#39;,#&#123;name&#125;,&#39;%&#39;)
             &lt;/if&gt;
             &lt;if test=&quot;gender != null&quot;&gt;
                 and gender = #&#123;gender&#125;
             &lt;/if&gt;
             &lt;if test=&quot;begin != null and end != null&quot;&gt;
                 and entrydate between #&#123;begin&#125; and #&#123;end&#125;
             &lt;/if&gt;

        order by update_time desc
